// ═══════════════════════════════════════════════════════════════════════════════
// 🦅 NEXUS + 🐴 CLAUDE - THE BRAIN LOGIC v5.0 HU
// ═══════════════════════════════════════════════════════════════════════════════
// ADVANCED GEO-CLUSTER SYSTEM - TÁVOLSÁG-ALAPÚ INTELLIGENS ZÓNÁZÁS
// 
// LOGIKA:
// - Egy nap = egy fő régió (fizikai korlátok miatt)
// - Zónán belül: 30 perc travel buffer
// - Szomszédos zóna: 90 perc travel buffer
// - Távoli zóna: TILTOTT (nem kombinálható egy napra)
// - BALATON = külön nagy zóna (belső HU része)
// ═══════════════════════════════════════════════════════════════════════════════

const normalizedData = $('Normalize Payload - HU').first().json;
const newBooking = normalizedData.body;
const calendarItems = $('Check Day Schedule').all();
const existingEvents = calendarItems.filter(item => item.json.id);

// ── AXR 0.2: a node tenyleges inputja - amit a Brain VALOBAN olvas ──
const __axrInput = {
  normalized_body: newBooking,
  calendar_events: calendarItems.map(i => i.json)
};

console.log('🧠 Brain Logic HU v5.0 Input:', {
    location: newBooking.location,
    duration: newBooking.duration,
    date: newBooking.date,
    slotStart: newBooking.slotStartTime
});

// ═══════════════════════════════════════════════════════════════════════════════
// CONFIGURATION
// ═══════════════════════════════════════════════════════════════════════════════
const WORK_START = "09:00";
const WORK_END = "17:00";
const SETUP_TIME = 20;

// Travel buffers based on zone relationship
const TRAVEL_BUFFER_SAME_ZONE = 30;       // Ugyanazon zónán belül
const TRAVEL_BUFFER_NEIGHBOR = 90;         // Szomszédos zónák között
const TRAVEL_BUFFER_CROSS_BORDER = 60;     // AT-HU határ menti zónák között

// ═══════════════════════════════════════════════════════════════════════════════
// GEO-CLUSTER DEFINITIONS v5.0 - HUNGARY + BORDER AUSTRIA
// ═══════════════════════════════════════════════════════════════════════════════

const GEO_CLUSTERS = {
    // ═══════════════════════════════════════════════════════════════════════════
    // MAGYAR ZÓNÁK - AKTÍV SZOLGÁLTATÁSI TERÜLETEK
    // ═══════════════════════════════════════════════════════════════════════════

    "GYOR_PAPA": {
        name: "Győr-Pápa régió",
        country: "HU",
        zipPrefixes: ["90", "91"],
        cities: ["győr", "gyor", "pápa", "papa", "pannonhalma", "csorna",
                 "tét", "tet", "bágyogszovát", "bagyogszovat", "bodonhely"]
    },

    "SOPRON_HATARMENTI": {
        name: "Sopron & Határmenti",
        country: "HU",
        zipPrefixes: ["94", "93", "92"],
        cities: ["sopron", "fertőd", "fertod", "fertőrákos", "fertorakos",
                 "nagycenk", "ágfalva", "agfalva", "fertőszentmiklós", "fertoszentmiklos",
                 "hegyeshalom", "rajka", "levél", "level", "jánossomorja", "janossomorja",
                 "mosonmagyaróvár", "mosonmagyarovar", "kapuvár", "kapuvar"]
    },

    "SZOMBATHELY_VAS": {
        name: "Szombathely & Vas megye",
        country: "HU",
        zipPrefixes: ["97", "98", "99"],
        cities: ["szombathely", "kőszeg", "koszeg", "szentgotthárd", "szentgotthard",
                 "körmend", "kormend", "csepreg", "sárvár", "sarvar", "celldömölk", "celldomolk",
                 "vasvár", "vasvar", "répcelak", "repcelak"]
    },

    "BALATON": {
        name: "Balaton régió",
        country: "HU",
        zipPrefixes: ["82", "83", "84", "86", "87", "88"],
        cities: [
            // Északi part
            "balatonfüred", "balatonfured", "tihany", "balatonalmádi", "balatonalmadi",
            "révfülöp", "revfulop", "balatonkenese", "balatonfűzfő", "balatonfuzfo",
            "badacsony", "alsóörs", "alsoors", "csopak", "balatonudvari",
            // Déli part
            "siófok", "siofok", "zamárdi", "zamardi", "balatonföldvár", "balatonfoldvar",
            "balatonlelle", "fonyód", "fonyod", "balatonboglár", "balatonboglar",
            "balatonszemes", "balatonszárszó", "balatonszarszo", "balatonmáriafürdő",
            // Nyugati part
            "keszthely", "hévíz", "heviz", "tapolca", "balatongyörök", "balatongyorok",
            "gyenesdiás", "gyenesdias", "vonyarcvashegy", "badacsonytomaj",
            // Környék
            "veszprém", "veszprem", "herend", "ajka", "várpalota", "varpalota",
            "zalaegerszeg", "nagykanizsa"
        ]
    },

    "SZEKESFEHERVAR": {
        name: "Székesfehérvár régió",
        country: "HU",
        zipPrefixes: ["80", "81", "28", "29", "85"],
        cities: ["székesfehérvár", "szekesfehervar", "dunaújváros", "dunaujvaros",
                 "mór", "mor", "bicske", "martonvásár", "martonvasar", "velence",
                 "tatabánya", "tatabanya", "tata", "komárom", "komarom"]
    },

    // ═══════════════════════════════════════════════════════════════════════════
    // OSZTRÁK HATÁR MENTI ZÓNÁK (HU rendszerből elérhető)
