    "AT_BURGENLAND_NORD": {
        name: "Nordburgenland (AT)",
        country: "AT",
        zipPrefixes: ["24", "70", "71"],
        cities: ["eisenstadt", "kismarton", "neusiedl", "nezsider", "parndorf", "pándorfalu",
                 "kittsee", "mattersburg", "nagymarton", "rust", "mörbisch", "morbisch"]
    },

    "AT_BURGENLAND_SUED": {
        name: "Südburgenland (AT)",
        country: "AT",
        zipPrefixes: ["72", "73", "74", "75", "76"],
        cities: ["oberwart", "felsőőr", "felsoor", "güssing", "guessing", "németújvár",
                 "jennersdorf", "gyanafalva", "pinkafeld", "pinkafő", "pinkafo",
                 "oberpullendorf", "felsőpulya", "felsopulya"]
