// ═══════════════════════════════════════════════════════════════════════════════
// ⏰ SLOT STILL FREE CHECK v2.0 - HU
// ═══════════════════════════════════════════════════════════════════════════════
// Ellenőrzi hogy a kiválasztott időpont még szabad-e a friss Calendar adatok alapján
// ═══════════════════════════════════════════════════════════════════════════════

// A frissen lekért események
const freshEvents = $('Fresh Calendar Check').all();

// FIX: Nincs "body" mező a normalized payload-ban!
const payload = $('Normalize Payload - HU').first().json.body;  // ← .body HOZZÁADVA!

// ── AXR 0.2: a node tenyleges inputja - amit a Slot Still Free VALOBAN olvas ──
const __axrInput = {
  normalized_body: payload,
  fresh_calendar_events: freshEvents.map(i => i.json)
};

// FIX: Helyes property nevek
const requestedStart = payload.slotStart || payload.slotStartTime || "09:00";
const requestedEnd = payload.slotEnd || payload.slotEndTime || "11:00";

console.log('⏰ Slot Still Free Check:', {
    requestedSlot: `${requestedStart} - ${requestedEnd}`,
    existingEventsCount: freshEvents.length,
    date: payload.bookingDate
});

// Van-e ütközés?
let conflict = false;
let conflictInfo = null;

for (const event of freshEvents) {
    // Skip ha nincs valid event data
    if (!event.json || !event.json.start?.dateTime || !event.json.end?.dateTime) {
        continue;
    }

    const eventStart = event.json.start.dateTime.split('T')[1]?.substring(0,5);
    const eventEnd = event.json.end.dateTime.split('T')[1]?.substring(0,5);

    if (!eventStart || !eventEnd) continue;

    console.log('  → Checking event:', {
        summary: event.json.summary,
        eventSlot: `${eventStart} - ${eventEnd}`,
        requestedSlot: `${requestedStart} - ${requestedEnd}`
    });

    // Átfedés ellenőrzés
    // Ha a kért kezdés < esemény vége ÉS kért vége > esemény kezdete → ÜTKÖZÉS
    if (requestedStart < eventEnd && requestedEnd > eventStart) {
        conflict = true;
        conflictInfo = {
            existingStart: eventStart,
            existingEnd: eventEnd,
            summary: event.json.summary || 'Foglalás',
            location: event.json.location || 'Nincs megadva'
        };

        console.log('  ❌ ÜTKÖZÉS!', conflictInfo);
        break;
    }
}

if (!conflict) {
    console.log('  ✅ Slot szabad!');
}

return [{
    json: {
        slotFree: !conflict,
        conflict: conflict,
        conflictInfo: conflictInfo,
        requestedSlot: {
            start: requestedStart,
            end: requestedEnd,
            date: payload.bookingDate
        },
        // Pass through the full payload for next nodes
        ...payload,
